 Qc("src/consensus/tx_check.cpp", "bad-cb-length", "bad-txns-prevout-null"),
 Qc("src/validation.cpp", "if (halvings >= 64)", "nSubsidy >>= halvings;", "bad-cb-amount", "coinbase pays too much"),
